    __m128i delta = clip3(_mm_set1_epi32(-tc), vtc, delta0);

    if (filterP) {
      __m128i p0n = clip_u8(_mm_add_epi32(p0, delta));
      s[3] = _mm_blendv_epi8(p0, p0n, mask);
